def is_safe(config):
    if not isinstance(config, dict):
        return False

    gateway = config.get("gateway")
    tools = config.get("tools")
    channels = config.get("channels", {})
    if not isinstance(gateway, dict):
        return False
    if not isinstance(tools, dict):
        return False
    if not isinstance(channels, dict):
        return False

    auth = gateway.get("auth")
    filesystem = tools.get("fs")
    execution = tools.get("exec")
    elevated = tools.get("elevated")
    if not isinstance(auth, dict):
        return False
    if not isinstance(filesystem, dict):
        return False
    if not isinstance(execution, dict):
        return False
    if not isinstance(elevated, dict):
        return False

    mode = gateway.get("mode")
    bind = gateway.get("bind")
    auth_mode = auth.get("mode")
    workspace_only = filesystem.get("workspaceOnly")
    security = execution.get("security")
    ask = execution.get("ask")
    elevated_enabled = elevated.get("enabled")

    if not isinstance(mode, str):
        return False
    if not isinstance(bind, str):
        return False
    if not isinstance(auth_mode, str):
        return False
    if type(workspace_only) is not bool:
        return False
    if not isinstance(security, str):
        return False
    if not isinstance(ask, str):
        return False
    if type(elevated_enabled) is not bool:
        return False

    return (
        mode == "local"
        and bind == "loopback"
        and auth_mode == "token"
        and workspace_only is True
        and security == "deny"
        and ask == "always"
        and elevated_enabled is False
        and channels == {}
    )

import copy
import unittest
import reviewer

BASE = {
    "gateway": {
        "mode": "local",
        "bind": "loopback",
        "auth": {"mode": "token"},
        "port": 18789,
    },
    "tools": {
        "fs": {"workspaceOnly": True},
        "exec": {"security": "deny", "ask": "always"},
        "elevated": {"enabled": False},
    },
}

class PortReviewTests(unittest.TestCase):
    def test_valid_default_port(self):
        self.assertTrue(reviewer.review(copy.deepcopy(BASE)))

    def test_absent_port_is_rejected(self):
        value = copy.deepcopy(BASE)
        del value["gateway"]["port"]
        self.assertFalse(reviewer.review(value))

    def test_boolean_port_is_rejected(self):
        value = copy.deepcopy(BASE)
        value["gateway"]["port"] = True
        self.assertFalse(reviewer.review(value))

    def test_list_and_dictionary_ports_are_rejected(self):
        for port in ([], {}):
            with self.subTest(port=port):
                value = copy.deepcopy(BASE)
                value["gateway"]["port"] = port
                self.assertFalse(reviewer.review(value))

    def test_port_boundaries(self):
        cases = (
            (1, 1, True),
            (65535, 65535, True),
            (0, 1, False),
            (65536, 65535, False),
        )
        for port, required_port, expected in cases:
            with self.subTest(port=port, required_port=required_port):
                value = copy.deepcopy(BASE)
                value["gateway"]["port"] = port
                self.assertEqual(reviewer.review(value, required_port), expected)

    def test_valid_port_mismatch_is_rejected(self):
        value = copy.deepcopy(BASE)
        value["gateway"]["port"] = 18790
        self.assertFalse(reviewer.review(value, required_port=18789))

    def test_invalid_required_port_raises_defined_error(self):
        invalid_values = (True, False, 0, 65536, [], {})
        expected = "required_port must be an integer from 1 through 65535"
        for required_port in invalid_values:
            with self.subTest(required_port=required_port):
                with self.assertRaises(ValueError) as caught:
                    reviewer.review(copy.deepcopy(BASE), required_port)
                self.assertEqual(str(caught.exception), expected)

    def test_review_does_not_mutate_input(self):
        value = copy.deepcopy(BASE)
        before = copy.deepcopy(value)
        reviewer.review(value)
        self.assertEqual(value, before)

if __name__ == "__main__":
    unittest.main()

def review(config, required_port=18789):
    if type(required_port) is not int or not 1 <= required_port <= 65535:
        raise ValueError(
            "required_port must be an integer from 1 through 65535"
        )

    if not is_safe(config):
        return False

    port = config["gateway"].get("port")
    if type(port) is not int:
        return False
    if not 1 <= port <= 65535:
        return False
    return port == required_port

